/**
 * @suppress
 */
public object FfiConverterTypeNmpApp: FfiConverter<NmpApp, Pointer> {

    override fun lower(value: NmpApp): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): NmpApp {
        return NmpApp(value)
    }

    override fun read(buf: ByteBuffer): NmpApp {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: NmpApp) = 8UL

    override fun write(value: NmpApp, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



