// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceUpdateSink {
    internal object `onUpdate`: UniffiCallbackInterfaceUpdateSinkMethod0 {
        override fun callback(`uniffiHandle`: Long,`frame`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeUpdateSink.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onUpdate`(
                    FfiConverterByteArray.lift(`frame`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeUpdateSink.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceUpdateSink.UniffiByValue(
        `onUpdate`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_nmp_uniffi_fn_init_callback_vtable_updatesink(vtable)
    }
}

